import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Игровая политика сервера","description":"","frontmatter":{"pageId":"admins/gameplay-policy","contentRevision":1},"headers":[],"relativePath":"ru/admins/gameplay-policy.md","filePath":"ru/admins/gameplay-policy.md"}'),l={name:"ru/admins/gameplay-policy.md"};function o(n,a,s,d,c,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="игровая-политика-сервера" tabindex="-1">Игровая политика сервера <a class="header-anchor" href="#игровая-политика-сервера" aria-label="Permalink to &quot;Игровая политика сервера&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>До открытия сервера объяви правила экономики, защиты новичков, рейдов, событий и хранения. Economy управляет лимитами посылок/лотов, комиссией, сбором хранения и запретом действий при угрозе. Raids задаёт число рейдеров, cooldown, добычу, мирный режим и сроки. Incidents включает каталог, очередь и цены. Live задаёт таймауты, паузы и ограничения потоков.</p><p>Integrity контролирует dev mode, изменение богатства и модификации сценария. Hygiene архивирует достаточно старые неактивные колонии при условиях богатства/возраста и определяет публичные диапазоны богатства. Отключение конкретной проверки требует понимания её значения, а не случайного нуля.</p><p>Для инцидента сначала заморозь нужную подсистему, сохрани id и аудит, изучи эскроу, затем отмени или разморозь. Проверяй возврат почтой.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Константы аукционов, закупок, соцсистемы и влияния не обязательно конфигурируемы. Сбор хранения может создавать долг. Заморозка откладывает аукционный расчёт, не означает бесплатный возврат. Режим влияния не даёт территориальных прав.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./configuration">Справочник конфигурации</a></li><li><a href="./administration">Панель и модерация</a></li><li><a href="./../players/raids-incidents">Рейды и платные события</a></li></ul>',10)])])}const u=e(l,[["render",o]]);export{h as __pageData,u as default};
